                new UMGPartyCognitionBlock("COG_LOW_HEALTH_PARTY", "InGameCognition", "low health party", "Low party health should bias speech toward triage and caution.", Tags("damaged", "low health", "wounds"), Tags("Acknowledge injury and caution.", "Suggest care without claiming action completion."), Tags("Read-only hook."), Tags("cognition", "health")),
