                new UMGPartyCognitionBlock("COG_CORPSE_LOOTED", "InGameCognition", "corpse looted", "A safely looted monster corpse should bias speech toward brief recovery and regrouping.", Tags("corpse looted", "loot complete"), Tags("Do not list every item in normal speech.", "Use logs for detail."), Tags("No debug dump visible."), Tags("cognition", "loot")),
                new UMGPartyCognitionBlock("COG_BURDEN_HIGH", "InGameCognition", "burden high", "High pack burden should bias speech toward caution, weight management, and supply discipline.", Tags("burden", "heavy", "pack"), Tags("Name burden plainly.", "Avoid travel-to-bank claims."), Tags("Read-only hook."), Tags("cognition", "burden")),
                new UMGPartyCognitionBlock("COG_PACK_FULL", "InGameCognition", "pack full", "A full pack should bias speech toward skipping low-value loot or unloading junk.", Tags("full pack", "overweight"), Tags("Keep gold and supplies protected.", "Drop only low-priority junk by policy."), Tags("Do not destroy items."), Tags("cognition", "burden")),
                new UMGPartyCognitionBlock("COG_JUNK_DROPPED", "InGameCognition", "junk dropped", "Dropped junk should be treated as battlefield weight management, not item destruction.", Tags("junk dropped", "unload"), Tags("Confirm briefly if needed.", "Do not expose item dump in normal speech."), Tags("No JSON/debug leakage."), Tags("cognition", "burden")),
                new UMGPartyCognitionBlock("COG_BANKING_NEEDED", "InGameCognition", "banking needed", "Banking need should be recognized but travel to a bank remains deferred to a later phase.", Tags("bank", "deposit", "too much loot"), Tags("Say banking is deferred if asked.", "Do not path to bank from this hook."), Tags("Read-only hook."), Tags("cognition", "banking")),
