                new UMGPartyCognitionBlock("COG_HEAL_POTION_USED", "InGameCognition", "heal potion used", "A heal potion use should bias speech toward staying upright and avoiding panic.", Tags("heal_potion_used"), Tags("Confirm briefly if needed."), Tags("Do not spam every potion use."), Tags("cognition", "potions")),
